def sort_docs(docs, spec):
    def keyer(field):
        def key(doc):
            v = doc.get(field)
            if v is None:
                return (0, 0)
            if isinstance(v, bool):
                return (3, v)
            if isinstance(v, (int, float)):
                return (1, v)
            return (2, v)
        return key

    out = list(docs)
    for field, direction in reversed(spec):
        out.sort(key=keyer(field), reverse=(direction == -1))
    return out

