mongo-explain-scan-count.solution:
def explain(docs, index, query):
    ops = {"$gt": lambda a, b: a > b, "$gte": lambda a, b: a >= b,
           "$lt": lambda a, b: a < b, "$lte": lambda a, b: a <= b}

    def holds(doc, field):
        if field not in doc:
            return False
        cond = query[field]
        if isinstance(cond, dict):
            return all(ops[op](doc[field], x) for op, x in cond.items())
        return doc[field] == cond

    prefix = []
    for field in index or []:
        if field not in query:
            break
        prefix.append(field)
        if isinstance(query[field], dict):
            break
    n_returned = sum(1 for d in docs if all(holds(d, f) for f in query))
    if not prefix:
        return {"stage": "COLLSCAN", "keysExamined": 0, "docsExamined": len(docs), "nReturned": n_returned}
    keys = [d for d in docs if all(holds(d, f) for f in prefix)]
    others = [f for f in index if f in query and f not in prefix]
    fetched = [d for d in keys if all(holds(d, f) for f in others)]
    return {"stage": "IXSCAN", "keysExamined": len(keys), "docsExamined": len(fetched), "nReturned": n_returned}

mongo-ttl-sweep.solution:
def ttl_timeline(docs, field, expire_after, sweep_times):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def expiry(doc):
        v = doc.get(field)
        if isinstance(v, list):
            nums = [x for x in v if is_num(x)]
            v = min(nums) if nums else None
        return v + expire_after if is_num(v) else None

    alive = [(d["_id"], expiry(d)) for d in docs]
    out = []
    for now in sweep_times:
        gone = [i for i, e in alive if e is not None and e <= now]
        alive = [(i, e) for i, e in alive if e is None or e > now]
        out.append(gone)
    return out

mongo-unique-violations.solution:
def insert_many(existing, new_docs, fields, ordered, sparse):
    def key(doc):
        if sparse and not any(f in doc for f in fields):
            return None
        return tuple(doc.get(f) for f in fields)

    seen = set()
    for doc in existing:
        k = key(doc)
        if k is not None:
            seen.add(k)
    inserted, errors = [], []
    for i, doc in enumerate(new_docs):
        k = key(doc)
        if k is not None and k in seen:
            errors.append(i)
            if ordered:
                break
            continue
        if k is not None:
            seen.add(k)
        inserted.append(i)
    return {"inserted": inserted, "errors": errors}

mongo-aggregate-pipeline.solution:
def aggregate(collections, name, pipeline):
    cmp = {"$gt": lambda a, b: a > b, "$gte": lambda a, b: a >= b,
           "$lt": lambda a, b: a < b, "$lte": lambda a, b: a <= b}

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def match(doc, q):
        for field, cond in q.items():
            present = field in doc
            if not isinstance(cond, dict):
                if not present or doc[field] != cond:
                    return False
                continue
            for op, x in cond.items():
                if op == "$ne":
                    if present and doc[field] == x:
                        return False
                elif op == "$in":
                    if not present or doc[field] not in x:
                        return False
                elif not present or not cmp[op](doc[field], x):
                    return False
        return True

    def group(docs, spec):
        ref = spec["_id"]
        groups, order = {}, []
        for d in docs:
            key = d.get(ref[1:]) if isinstance(ref, str) else None
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append(d)
        out = []
        for key in order:
            row = {"_id": key}
            for field, acc in spec.items():
                if field == "_id":
                    continue
                (fn, expr), = acc.items()
                if isinstance(expr, str):
                    vals = [d[expr[1:]] for d in groups[key] if expr[1:] in d]
                else:
                    vals = [expr] * len(groups[key])
                if fn == "$push":
                    row[field] = vals
                    continue
                nums = [v for v in vals if is_num(v)]
                if fn == "$sum":
                    row[field] = sum(nums)
                elif fn == "$avg":
                    row[field] = sum(nums) / len(nums) if nums else None
                elif fn == "$min":
                    row[field] = min(nums) if nums else None
                elif fn == "$max":
                    row[field] = max(nums) if nums else None
            out.append(row)
        return out

    docs = [dict(d) for d in collections.get(name, [])]
    for stage in pipeline:
        (op, arg), = stage.items()
        if op == "$match":
            docs = [d for d in docs if match(d, arg)]
        elif op == "$project":
            out = []
            for d in docs:
                new = {}
                if arg.get("_id", 1) != 0 and "_id" in d:
                    new["_id"] = d["_id"]
                for k, v in arg.items():
                    if k == "_id":
                        continue
                    src = v[1:] if isinstance(v, str) else k
                    if src in d:
                        new[k] = d[src]
                out.append(new)
            docs = out
        elif op == "$group":
            docs = group(docs, arg)
        elif op == "$sort":
            for field, direction in reversed(list(arg.items())):
                docs.sort(key=lambda d: (d.get(field) is not None, 0 if d.get(field) is None else d[field]),
                          reverse=(direction == -1))
        elif op == "$limit":
            docs = docs[:arg]
        elif op == "$unwind":
            field = arg[1:]
            out = []
            for d in docs:
                v = d.get(field)
                if v is None:
                    continue
                if isinstance(v, list):
                    for item in v:
                        new = dict(d)
                        new[field] = item
                        out.append(new)
                else:
                    out.append(d)
            docs = out
        elif op == "$lookup":
            foreign = collections.get(arg["from"], [])
            out = []
            for d in docs:
                local = d.get(arg["localField"])
                wanted = local if isinstance(local, list) else [local]
                new = dict(d)
                new[arg["as"]] = [dict(f) for f in foreign if f.get(arg["foreignField"]) in wanted]
                out.append(new)
            docs = out
        else:
            raise ValueError("unsupported stage " + op)
    return docs

mongo-facet.solution:
def facet(docs, facets):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    result = {}
    for name, spec in facets.items():
        cond = spec.get("match", {})
        rows = [d for d in docs if all(k in d and d[k] == v for k, v in cond.items())]
        if "sortByCount" in spec:
            field = spec["sortByCount"]
            counts = {}
            for d in rows:
                key = d.get(field)
                counts[key] = counts.get(key, 0) + 1
            out = [{"_id": k, "count": c} for k, c in counts.items()]
            out.sort(key=lambda r: -r["count"])
            result[name] = out
        elif "bucket" in spec:
            field, bounds = spec["bucket"], spec["boundaries"]
            counts = {}
            for d in rows:
                v = d.get(field)
                key = "other"
                if is_num(v):
                    for lo, hi in zip(bounds, bounds[1:]):
                        if lo <= v < hi:
                            key = lo
                            break
                counts[key] = counts.get(key, 0) + 1
            out = [{"_id": lo, "count": counts[lo]} for lo in bounds[:-1] if lo in counts]
            if "other" in counts:
                out.append({"_id": "other", "count": counts["other"]})
            result[name] = out
        else:
            nums = [d[spec["stats"]] for d in rows if is_num(d.get(spec["stats"]))]
            if nums:
                result[name] = {"count": len(nums), "min": min(nums), "max": max(nums), "avg": sum(nums) / len(nums)}
            else:
                result[name] = {"count": 0, "min": None, "max": None, "avg": None}
    return result

mongo-embed-reference.solution:
def embed_children(parents, children, fk, as_field, limit):
    by_parent = {}
    for child in children:
        if fk in child:
            by_parent.setdefault(child[fk], []).append(child)
    out = []
    for parent in parents:
        kids = sorted(by_parent.get(parent["_id"], []), key=lambda c: c["_id"], reverse=True)
        total = len(kids)
        if limit is not None:
            kids = kids[:limit]
        new = dict(parent)
        new[as_field] = [{k: v for k, v in c.items() if k != fk} for c in kids]
        new[as_field + "_count"] = total
        out.append(new)
    return out

